function seed(){return GolfWorkOrders.demoSeed();}
async function init(){try{let courses;if(demo){courses=[{id:'juniper-cove-lakes',name:'Juniper Cove Golf Club — Lakes Course (DEMO COURSE)',url:'/test-drive/'}];user={name:'Demo Superintendent'};demoState=GolfWorkOrders.loadDemo(seed());$('crew-demo-role').hidden=false;const play=GolfPlaySession.create({onExpire(){location.replace('/test-drive/crew/?expired=1');}});for(const name of ['pointerdown','keydown','wheel','touchstart'])document.addEventListener(name,()=>play.touch(),{passive:true,capture:true});setInterval(()=>play.check(),5000);window.addEventListener('pagehide',()=>play.end());window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});}else{const {refreshSession}=await import('./identity-sdk.js');await refreshSession();const r=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});if(!r.ok){location.replace('/login/?required=crew');return;}user=await r.json();courses=user.courses||[];if(!courses.length){location.replace('/account/');return;}}const wanted=demo?courses[0].id:query.get('course');course=courses.find(c=>c.id===wanted)||(!wanted?courses[0]:null);if(!course)throw Error('This course is not available to your account. Open My account.');for(const c of courses){const o=el('option',c.name);o.value=c.id;$('crew-course').append(o);}$('crew-course').value=course.id;$('crew-course').disabled=courses.length<2;$('crew-person').textContent=demo?'Fictional demo crew':'Signed in as '+user.name;courseLinks();await load();const deep=query.get('ticket');const linked=state?.assignments[deep]||state?.workOrders?.[deep];if(linked)ticket(linked);else if(manager&&query.get('newWork')==='landscaping')assignmentForm(null,{workCategory:'Landscaping'});}catch(e){message(e.message,true);}}
$('crew-test-email').onclick=async()=>{if(demo){message('Demo only: no email is sent.');return;}const b=$('crew-test-email');b.disabled=true;try{const r=await fetch('/api/crew-email-test?course='+encodeURIComponent(course.id),{method:'POST',credentials:'same-origin'}),j=await r.json();if(!r.ok)throw Error(j.error);message('Test email accepted by the email service for '+j.recipient+'. Check the inbox and spam folder.');}catch(e){message(e.message,true);}finally{b.disabled=false;}};$('crew-add-worker').onclick=()=>workerForm();$('crew-assign').onclick=()=>assignmentForm();$('crew-copy').onclick=copyForm;$('crew-refresh').onclick=()=>load();$('crew-worker-filter').onchange=e=>{filter=e.target.value;render();};for(const b of document.querySelectorAll('[data-crew-view]'))b.onclick=()=>{view=b.dataset.crewView;render();};$('crew-today').onclick=()=>{anchor=M.day();render();};function move(n){anchor=view==='month'?monthShift(anchor,n):M.addDays(anchor,n*(view==='week'?7:1));render();}$('crew-previous').onclick=()=>move(-1);$('crew-next').onclick=()=>move(1);$('crew-preview-role').onchange=()=>accept(demoResult());$('crew-course').onchange=async()=>{if(dirty)return;const r=await fetch('/api/session',{cache:'no-store'});if(!r.ok){location.replace('/login/');return;}user=await r.json();course=user.courses.find(c=>c.id===$('crew-course').value);if(!course)return;state=null;filter='all';history.replaceState(null,'','?course='+encodeURIComponent(course.id));courseLinks();await load();};$('crew-password-show').onchange=e=>$('crew-new-password').type=e.target.checked?'text':'password';$('crew-password-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const password=$('crew-new-password').value,r=await fetch('/api/crew-password',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})}),result=await r.json();if(!r.ok)throw Error(result.error);const {login}=await import('./identity-sdk.js');await login(user.email,password);$('crew-new-password').value='';await load();}catch(e){message(e.message,true);}finally{button.disabled=false;}};setInterval(()=>{if(!demo&&!document.hidden&&!dialog.open&&!busy&&course)load(true);},30000);if(matchMedia('(max-width:760px)').matches){$('crew-roster-details').open=false;$('crew-zoom-help').textContent='Tap a date to see that day’s work. Times: America/New_York.';}await init();

// Read-only examples for the demo walkthrough; never inserted into state or storage.
let tourPriorRole=null,tourPriorFilter=null;
if(demo)window.GolfCrewTour={
 restore(){if(tourPriorRole===null)return;if(dialog.open)dialog.close();const selector=$('crew-preview-role');selector.value=tourPriorRole;selector.dispatchEvent(new Event('change'));filter=tourPriorFilter;render();tourPriorRole=tourPriorFilter=null;},
 preview(stage){
  const role=stage==='assistant'||['review','approve','history'].includes(stage)?'assistant':'worker';
  const selector=$('crew-preview-role');if(tourPriorRole===null){tourPriorRole=selector.value;tourPriorFilter=filter;}selector.value=role;selector.dispatchEvent(new Event('change'));
  if(stage==='worker'||stage==='assistant')return;
  const worker=state.workers['WRK-demo-jordan']||Object.values(state.workers)[0];
  const stamp=new Date().toISOString(),opener={id:'tour-super',name:'Sample Superintendent'},performer={id:'tour-worker',name:worker?.name||'Sample Worker'},reviewer={id:'tour-assistant',name:'Sample Assistant Superintendent'};
  const event=(kind,actor,note)=>({kind,actor,note,at:stamp});
  const history=[event('opened',opener,'Tour sample opened and assigned.')];
  if(['submit','review','approve','history'].includes(stage))history.push(event('worked',performer,'Replaced the damaged fitting and checked operation.'));
  if(['review','approve','history'].includes(stage))history.push(event('draft_closed',performer,'Work finished; inspection and closure approval requested.'));
  if(stage==='history')history.push(event('closed',reviewer,'Inspection passed. Closure approved.'));
  const a={id:'ASG-tour-preview',title:'TOUR SAMPLE · Emergency repair',workerId:worker?.id,hole:3,date:M.day(),startTime:'08:00',duration:60,maintenanceKind:'emergency',status:stage==='history'?'completed':['review','approve'].includes(stage)?'pending_closure':stage==='submit'?'in_progress':'scheduled',version:1,notes:'Read-only walkthrough example. No real work order is created.',openedBy:opener,history,...(stage==='history'?{closedBy:reviewer}:{})};
  if(['log','submit','approve'].includes(stage))ticketFlow(a,stage==='log'?'note':stage==='submit'?'submit':'approve');else ticket(a);
  dialog.prepend(el('p','WALKTHROUGH PREVIEW · Unsaved fictional example','crew-tour-preview'));
  for(const field of dialog.querySelectorAll('input,textarea'))field.readOnly=true;
  for(const field of dialog.querySelectorAll('select,button[type=submit]'))field.disabled=true;
 }
};

document.addEventListener('golf-language-change',()=>{const key=dialog.dataset.ticketId,a=state?.assignments[key]||state?.workOrders?.[key];if(dialog.open&&a)ticket(a);});
